#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn simple_transfer() {
        let a = Account::shared("ann", 100);
        let b = Account::shared("bob", 5);
        assert_eq!(transfer(&a, &b, 30), Ok(()));
        assert_eq!(a.borrow().balance, 70);
        assert_eq!(b.borrow().balance, 35);
        assert_eq!(a.borrow().history, vec![-30]);
        assert_eq!(b.borrow().history, vec![30]);
        assert_eq!(a.borrow().owner, "ann");
    }

    #[test]
    fn shared_handles_see_changes() {
        let a = Account::shared("ann", 50);
        let alias = Rc::clone(&a);
        let b = Account::shared("bob", 0);
        transfer(&alias, &b, 50).unwrap();
        assert_eq!(a.borrow().balance, 0);
        assert_eq!(Rc::strong_count(&a), 2);
    }

    #[test]
    fn errors_leave_state_untouched() {
        let a = Account::shared("ann", 10);
        let b = Account::shared("bob", 0);
        assert_eq!(transfer(&a, &a.clone(), 5), Err(TransferError::SameAccount));
        assert_eq!(transfer(&a, &b, 0), Err(TransferError::ZeroAmount));
        assert_eq!(transfer(&a, &b, 11), Err(TransferError::Insufficient { needed: 11, available: 10 }));
        assert_eq!(a.borrow().balance, 10);
        assert!(a.borrow().history.is_empty());
        assert!(b.borrow().history.is_empty());
    }

    #[test]
    fn total_counts_each_account_once() {
        let a = Account::shared("ann", 100);
        let b = Account::shared("bob", 5);
        let c = Account::shared("cat", 5);
        assert_eq!(total(&[a.clone(), b.clone(), a.clone(), c.clone(), b.clone()]), 110);
        assert_eq!(total(&[]), 0);
    }
}
